    // Simple words
    function payAmountWords($n) {
      $ones=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];
      $tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];
      if($n==0) return 'Zero';
      if($n<20) return $ones[$n];
      if($n<100) return $tens[intval($n/10)].($n%10?' '.$ones[$n%10]:'');
      if($n<1000) return $ones[intval($n/100)].' Hundred'.($n%100?' '.payAmountWords($n%100):'');
      if($n<1000000) return payAmountWords(intval($n/1000)).' Thousand'.($n%1000?' '.payAmountWords($n%1000):'');
      return (string)$n;
    }
