<script>
function openModal(id)  { document.getElementById(id).classList.add('open'); }
function closeModal(id) { document.getElementById(id).classList.remove('open'); }
function openEdit(p) {
  document.getElementById('editPsId').value    = p.id;
  document.getElementById('editEmpName').textContent = p.name;
  document.getElementById('editBasic').value   = p.basic;
  document.getElementById('editOT').value      = p.ot;
  document.getElementById('editLWOP').value    = p.lwop;
  document.getElementById('editOther').value   = p.other;
  openModal('editPayslipModal');
}

document.querySelectorAll('.overlay').forEach(o => {
  o.addEventListener('click', e => { if (e.target===o) o.classList.remove('open'); });
});
</script>
